<script lang="ts">import {createCheckboxController} from "@civaria/core";import {normalizeSvelteProps} from "./internal.js";let {checked=$bindable(false),defaultChecked=false,disabled=false,required=false,label="",name,value="on",id="civ-checkbox"}=$props<{checked?:boolean;defaultChecked?:boolean;disabled?:boolean;required?:boolean;label?:string;name?:string;value?:string;id?:string}>();const controller=createCheckboxController({id,defaultChecked:checked??defaultChecked,disabled,onCheckedChange:next=>checked=next});let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>{if(checked!==state.checked)controller.syncChecked(checked)});function p(kind:"root"|"control"|"hiddenInput"){state;return normalizeSvelteProps(kind==="root"?controller.getRootProps():kind==="control"?controller.getControlProps():controller.getHiddenInputProps(name,value,required))}</script><label {...p("root")} class="civ-checkbox"><span {...p("control")} class="civ-checkbox__control"></span><input {...p("hiddenInput")} class="civ-checkbox__hiddenInput" />{label}</label>
